export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon?: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type AbortFailedAt = Provider | "repository";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields &
  Readonly<{
    state: "queued";
  }>;

type DispatchedShipment = ShipmentFields &
  Readonly<{
    state: "dispatched";
    provider: Provider;
    bookingId: string;
    dispatchedAtMs: number;
  }>;

type DeferredShipment = ShipmentFields &
  Readonly<{
    state: "deferred";
    nextProvider: Provider;
    retryAtMs: number;
    rejections: readonly Rejection[];
  }>;

type UnavailableShipment = ShipmentFields &
  Readonly<{
    state: "unavailable";
    rejections: readonly Rejection[];
  }>;

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: AbortFailedAt;
  classification: AbortClassification;
  rejections: readonly Rejection[];
}>;

type ErrorBody =
  | Readonly<{ code: "invalid_command" | "not_found" | "service_unavailable" }>
  | AbortBody;

export interface ServiceResponse {
  status: number;
  body: PublicShipment | ErrorBody;
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierOutcome =
  | Readonly<{ kind: "confirmed"; bookingId: string }>
  | Readonly<{ kind: "refused"; rejection: Rejection }>
  | Readonly<{ kind: "throttled"; retryAtMs: number }>
  | Readonly<{ kind: "aborted"; classification: Exclude<AbortClassification, "repository_failure"> }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isPositiveSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseRejections(value: unknown): readonly Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const rejections = value.map((item): Rejection | undefined => {
    if (!isObject(item) || !isProvider(item.provider) || !isRefusalReason(item.reason)) {
      return undefined;
    }
    return { provider: item.provider, reason: item.reason };
  });

  if (rejections.some((item) => item === undefined)) {
    return undefined;
  }

  return rejections.filter((item): item is Rejection => item !== undefined);
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    !isNonemptyString(value.id) ||
    !isNonemptyString(value.routeCode) ||
    !isPositiveSafeInteger(value.parcelGrams)
  ) {
    return undefined;
  }

  const base = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } as const;

  if (value.state === "queued") {
    return { ...base, state: "queued" };
  }

  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonemptyString(value.bookingId) &&
    typeof value.dispatchedAtMs === "number" &&
    Number.isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...base,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }

  const rejections = parseRejections(value.rejections);
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    typeof value.retryAtMs === "number" &&
    Number.isSafeInteger(value.retryAtMs) &&
    value.retryAtMs >= 0 &&
    rejections !== undefined
  ) {
    return {
      ...base,
      state: "deferred",
      nextProvider: value.nextProvider,
      retryAtMs: value.retryAtMs,
      rejections,
    };
  }

  if (value.state === "unavailable" && rejections !== undefined) {
    return {
      ...base,
      state: "unavailable",
      rejections,
    };
  }

  return undefined;
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };

  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections,
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: shipment.rejections,
      };
  }
}

function dispatchStatus(shipment: StoredShipment): number {
  switch (shipment.state) {
    case "queued":
    case "dispatched":
      return 200;
    case "deferred":
      return 202;
    case "unavailable":
      return 422;
  }
}

function abortBody(
  shipmentId: string,
  failedAt: AbortFailedAt,
  classification: AbortClassification,
  rejections: readonly Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections,
  };
}

function logAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: AbortFailedAt,
  classification: AbortClassification,
  rejections: readonly Rejection[],
): void {
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections,
  });
}

function abortResponse(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: AbortFailedAt,
  classification: AbortClassification,
  rejections: readonly Rejection[],
): ServiceResponse {
  logAbort(dependencies, shipmentId, failedAt, classification, rejections);
  return {
    status: 500,
    body: abortBody(shipmentId, failedAt, classification, rejections),
  };
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function classifyAtlasRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error) || typeof error.code !== "string") {
    return { kind: "aborted", classification: "unknown_failure" };
  }

  if (error.code === "cannot_ship") {
    if (!isRefusalReason(error.reason)) {
      return { kind: "aborted", classification: "invalid_provider_response" };
    }
    return {
      kind: "refused",
      rejection: { provider: "atlas", reason: error.reason },
    };
  }

  if (error.code === "rate_limited") {
    if (
      typeof error.retryAtMs !== "number" ||
      !Number.isSafeInteger(error.retryAtMs) ||
      error.retryAtMs <= nowMs
    ) {
      return { kind: "aborted", classification: "invalid_provider_response" };
    }
    return { kind: "throttled", retryAtMs: error.retryAtMs };
  }

  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyBeaconRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error) || typeof error.type !== "string") {
    return { kind: "aborted", classification: "unknown_failure" };
  }

  if (error.type === "rejected") {
    if (!isObject(error.details) || !isRefusalReason(error.details.reason)) {
      return { kind: "aborted", classification: "invalid_provider_response" };
    }
    return {
      kind: "refused",
      rejection: { provider: "beacon", reason: error.details.reason },
    };
  }

  if (error.type === "throttled") {
    if (
      !isObject(error.details) ||
      typeof error.details.retryAtMs !== "number" ||
      !Number.isSafeInteger(error.details.retryAtMs) ||
      error.details.retryAtMs <= nowMs
    ) {
      return { kind: "aborted", classification: "invalid_provider_response" };
    }
    return { kind: "throttled", retryAtMs: error.details.retryAtMs };
  }

  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyConfirmation(provider: Provider, response: unknown): CarrierOutcome {
  if (provider === "atlas") {
    if (isObject(response) && isNonemptyString(response.bookingId)) {
      return { kind: "confirmed", bookingId: response.bookingId };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }

  if (isObject(response) && isNonemptyString(response.reference)) {
    return { kind: "confirmed", bookingId: response.reference };
  }
  return { kind: "aborted", classification: "invalid_provider_response" };
}

async function callCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierOutcome> {
  try {
    const response =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon?.reserve(request);
    return classifyConfirmation(provider, response);
  } catch (error: unknown) {
    return provider === "atlas"
      ? classifyAtlasRejection(error, nowMs)
      : classifyBeaconRejection(error, nowMs);
  }
}

function addRejection(
  rejections: readonly Rejection[],
  rejection: Rejection,
): readonly Rejection[] {
  return rejections.some((item) => item.provider === rejection.provider)
    ? rejections
    : [...rejections, rejection];
}

function baseFields(shipment: StoredShipment): ShipmentFields {
  return {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  record: StoredShipment,
  event: Record<string, unknown>,
  status: number,
  rejectionsForSaveFailure: readonly Rejection[],
): Promise<ServiceResponse> {
  try {
    await dependencies.repository.save(shipment.id, record);
  } catch {
    return abortResponse(
      dependencies,
      shipment.id,
      "repository",
      "repository_failure",
      rejectionsForSaveFailure,
    );
  }

  dependencies.logger.info(event);
  return { status, body: publicShipment(record) };
}

async function persistConfirmed(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  provider: Provider,
  bookingId: string,
  nowMs: number,
  rejectionsForSaveFailure: readonly Rejection[],
): Promise<ServiceResponse> {
  const dispatched: DispatchedShipment = {
    ...baseFields(shipment),
    state: "dispatched",
    provider,
    bookingId,
    dispatchedAtMs: nowMs,
  };

  return saveDecision(
    dependencies,
    shipment,
    dispatched,
    {
      shipmentId: shipment.id,
      action: "dispatched",
      provider,
    },
    200,
    rejectionsForSaveFailure,
  );
}

async function persistDeferred(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  nextProvider: Provider,
  retryAtMs: number,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  const deferred: DeferredShipment = {
    ...baseFields(shipment),
    state: "deferred",
    nextProvider,
    retryAtMs,
    rejections,
  };

  return saveDecision(
    dependencies,
    shipment,
    deferred,
    {
      shipmentId: shipment.id,
      action: "deferred",
      provider: nextProvider,
      retryAtMs,
      rejections,
    },
    202,
    rejections,
  );
}

async function persistUnavailable(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  const unavailable: UnavailableShipment = {
    ...baseFields(shipment),
    state: "unavailable",
    rejections,
  };

  return saveDecision(
    dependencies,
    shipment,
    unavailable,
    {
      shipmentId: shipment.id,
      action: "unavailable",
      rejections,
    },
    422,
    rejections,
  );
}

function nextProviderAfterRefusal(provider: Provider): Provider | undefined {
  return provider === "atlas" ? "beacon" : undefined;
}

async function attemptDispatch(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  provider: Provider,
  command: Extract<Command, { op: "dispatch" }>,
  priorRejections: readonly Rejection[],
): Promise<ServiceResponse> {
  if (priorRejections.some((rejection) => rejection.provider === provider)) {
    const nextProvider = nextProviderAfterRefusal(provider);
    if (nextProvider === undefined) {
      return persistUnavailable(dependencies, shipment, priorRejections);
    }
    return attemptDispatch(dependencies, shipment, nextProvider, command, priorRejections);
  }

  const outcome = await callCarrier(
    dependencies,
    provider,
    providerRequest(shipment, command.recipient),
    command.nowMs,
  );

  switch (outcome.kind) {
    case "confirmed":
      return persistConfirmed(
        dependencies,
        shipment,
        provider,
        outcome.bookingId,
        command.nowMs,
        priorRejections,
      );
    case "throttled":
      return persistDeferred(
        dependencies,
        shipment,
        provider,
        outcome.retryAtMs,
        priorRejections,
      );
    case "aborted":
      return abortResponse(
        dependencies,
        shipment.id,
        provider,
        outcome.classification,
        priorRejections,
      );
    case "refused": {
      const rejections = addRejection(priorRejections, outcome.rejection);
      const nextProvider = nextProviderAfterRefusal(provider);
      if (nextProvider === undefined) {
        return persistUnavailable(dependencies, shipment, rejections);
      }
      return attemptDispatch(dependencies, shipment, nextProvider, command, rejections);
    }
  }
}

async function handleDispatch(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
): Promise<ServiceResponse> {
  if (shipment.state === "dispatched" || shipment.state === "unavailable") {
    return {
      status: dispatchStatus(shipment),
      body: publicShipment(shipment),
    };
  }

  if (shipment.state === "deferred") {
    if (command.nowMs < shipment.retryAtMs) {
      return { status: 202, body: publicShipment(shipment) };
    }
    return attemptDispatch(
      dependencies,
      shipment,
      shipment.nextProvider,
      command,
      shipment.rejections,
    );
  }

  return attemptDispatch(dependencies, shipment, "atlas", command, []);
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return abortResponse(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }

    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (shipment === undefined) {
      return abortResponse(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    return handleDispatch(dependencies, shipment, command);
  }

  return { handle };
}
